using System.Text.Json;
using ChartForgeX.Interactivity;
using ChartForgeX.Interactivity.Html;
using ChartForgeX.Rendering;
using Microsoft.Playwright;
using Xunit;
using static ChartForgeX.Tests.InteractiveChartBrowser;
namespace ChartForgeX.Tests;
public sealed partial class NativeTransitionBrowserTests {
    [BrowserTheory][InlineData("default",390,false,false)][InlineData("customrole",760,true,true)]
    public async Task ActualNativeScatterValueFramesKeepAuthoredMarkersAcceptedExportsAndExistingInitialLifetime(string policy,int width,bool dark,bool initial){if(!Enabled)return;var renderer=new HtmlInteractiveChartRenderer();HtmlChartSection Section(double value)=>renderer.PrepareSection(NativeScatterValueBeforeControls.Model(policy,value,width,dark),configure:options=>{options.Interaction.ChartId="native-scatter";options.Interaction.Enable(ChartInteractionFeatures.Export);});var from=Section(30);var to=Section(40);var frames=VisualValueCapture.NativeFrames(from.PreparedVisual,to.PreparedVisual,5,null);var payload=renderer.PrepareNativeTransitionJson(from,to,new HtmlNativeTransitionOptions(initial?HtmlNativeTransitionEffect.InitialValues:HtmlNativeTransitionEffect.Values,5));var name="scatter-browser-"+policy+"-"+width;
        await using var session=await BrowserProofFonts.OpenAsync(Page(initial?to:from),width+24,680);var page=session.Page;await ReadyAndPauseAsync(page);await page.EmulateMediaAsync(new PageEmulateMediaOptions{ReducedMotion=ReducedMotion.NoPreference});await page.EvaluateAsync("()=>{window.scatterChart=ChartForgeXCharts.get(document.querySelector('.cfx-interactive-chart'));window.scatterEvents=[];window.scatterRevision=scatterChart.sceneRevision;scatterChart.root.addEventListener('cfxupdated',event=>scatterEvents.push(event.detail));}");
        if(initial)await page.EvaluateAsync("payload=>scatterChart.presentInitial(payload,{sceneRevision:scatterChart.sceneRevision,motion:{duration:1000}})",payload);else await page.EvaluateAsync("reply=>scatterChart.update(reply.html,{sceneRevision:scatterChart.sceneRevision,transition:reply.payload,motion:{duration:1000}})",new{html=to.Html,payload});await page.Clock.RunForAsync(300);
        var observed=await page.EvaluateAsync<JsonElement>("()=>({before:scatterRevision,revision:scatterChart.sceneRevision,events:scatterEvents,value:scatterChart.root.querySelector('.cfx-stage>svg [data-cfx-observation-id=current]')?.dataset.cfxY,frame:scatterChart.root.querySelector('.cfx-native-motion-frame')?.outerHTML})");NativeRadialValueMotionTests.Capture(from,to,frames,payload,name);NativeRadialMotionBeforeControls.Save(name+".observed.json",observed.GetRawText());if(Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY") is {Length:>0} output)await page.ScreenshotAsync(new PageScreenshotOptions{Path=Path.Combine(output,name+".browser.png"),FullPage=true});
        Assert.Equal("40",observed.GetProperty("value").GetString());Assert.Equal(initial?0:1,observed.GetProperty("events").GetArrayLength());Assert.Equal(initial,observed.GetProperty("before").GetString()==observed.GetProperty("revision").GetString());await NativeValueFrameBrowserProof.AssertAsync(page,"[data-cfx-role=point][data-cfx-observation-id=current] [data-cfx-role="+(policy=="customrole"?"inspection-mark":"marker")+"]",name+"-ink");
        var download=await page.RunAndWaitForDownloadAsync(()=>page.Locator("[data-cfx-export=svg]").ClickAsync());var file=await download.PathAsync()??throw new InvalidOperationException("Scatter final export missing.");var exported=await File.ReadAllTextAsync(file);NativeRadialMotionBeforeControls.Save(name+".exported.svg",exported);var svg=System.Xml.Linq.XDocument.Parse(exported);Assert.Equal("40",svg.Descendants().Single(row=>(string?)row.Attribute("data-cfx-role")=="point"&&(string?)row.Attribute("data-cfx-observation-id")=="current").Attribute("data-cfx-y")!.Value);await page.EmulateMediaAsync(new PageEmulateMediaOptions{ReducedMotion=ReducedMotion.Reduce});Assert.Equal(0,await page.Locator(".cfx-native-motion-frame").CountAsync());await page.EvaluateAsync("()=>scatterChart.dispose()");AssertNoConsoleErrors(session);}
}
